return $input.all().map(item => {
  let raw = item.json.stdout ? item.json.stdout.join('\n') : '';
  let summary = `M1-F ❌ 未知错误`;

  if (raw.includes('任务结束。共处理')) {
    const match = raw.match(/任务结束。共处理 \(删除\/清空\) (\d+) 个目标。/);
    let oldestInfo = "";
    const indexMatch = raw.match(/Index 分时目录[\s\S]*?最远保留至: (\d{4}-\d{2}-\d{2})/);
    const etfMatch = raw.match(/ETF 分时目录[\s\S]*?最远保留至: (\d{4}-\d{2}-\d{2})/);
    if (indexMatch) oldestInfo += `\n大盘保留至: ${indexMatch[1]}`;
    if (etfMatch) oldestInfo += `\nETF保留至: ${etfMatch[1]}`;

    if (match) {
      summary = `M1-F ✅ 分时清理完毕\n共删除了 ${match[1]} 个历史文件，保留最近3天。${oldestInfo}`;
    }
  } else if (raw.includes('❌')) {
    summary = `M1-F ❌ 清理失败: ${raw.split('\n').find(l => l.includes('❌'))}`;
  }

  return { json: { summary } };
});
